// WARDEN-W1 Node 2: PII Scrub + HMAC Hash + Duplicate Check + Supabase Insert
const crypto = require('crypto');
const body = $input.first().json.body || $input.first().json;

// Validate required fields
if (!body.requesting_agent || !body.target_service || !body.payload_data) {
  return [{ json: { error_response: true, status_code: 400,
    response_body: { error: 'Missing required fields' } } }];
}

// Step 2a: PII strip
const piiPattern = /phone|email|ssn|dob|address|name|first|last/i;
const sanitized_payload = {};
for (const [key, value] of Object.entries(body.payload_data)) {
  if (!piiPattern.test(key)) { sanitized_payload[key] = value; }
}

// Step 2b: HMAC-SHA256
const hmacSecret = $env.WARDEN_HMAC_SECRET;
const security_hash = crypto
  .createHmac('sha256', hmacSecret)
  .update(JSON.stringify(sanitized_payload))
  .digest('hex');

// Step 2c: Duplicate check against Supabase
const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_SERVICE_KEY;
const dupCheck = await fetch(
  `${supabaseUrl}/rest/v1/warden_transactions?security_hash=eq.${security_hash}&status=neq.FAILED&select=id`,
  { headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}` } }
);
const dupRows = await dupCheck.json();
if (dupRows && dupRows.length > 0) {
  return [{ json: { error_response: true, status_code: 409,
    response_body: { error: 'Duplicate request', existing_id: dupRows[0].id } } }];
}

// Step 2d: Supabase insert
const insertRes = await fetch(`${supabaseUrl}/rest/v1/warden_transactions`, {
  method: 'POST',
  headers: { 'apikey': supabaseKey, 'Authorization': `Bearer ${supabaseKey}`,
    'Content-Type': 'application/json', 'Prefer': 'return=representation' },
  body: JSON.stringify({
    requesting_agent: body.requesting_agent, target_service: body.target_service,
    payload_data: sanitized_payload, status: 'PENDING', security_hash: security_hash })
});
const insertData = await insertRes.json();
if (!insertRes.ok) {
  return [{ json: { error_response: true, status_code: 500,
    response_body: { error: 'Database insert failed', detail: JSON.stringify(insertData) } } }];
}
const row = Array.isArray(insertData) ? insertData[0] : insertData;
return [{ json: { transaction_id: row.id, requesting_agent: body.requesting_agent,
  target_service: body.target_service, sanitized_payload: sanitized_payload,
  security_hash: security_hash, created_at: row.created_at, error_response: false } }];

// Extract risk summary from Gemini response, with fallback
const geminiResponse = $input.first().json;
const prevData = $('Respond PENDING').first().json;

let risk_summary = 'Unable to generate summary — review payload manually before approving.';
try {
  if (geminiResponse.candidates && geminiResponse.candidates[0]) {
    risk_summary = geminiResponse.candidates[0].content.parts[0].text.trim();
  }
} catch (e) {}

return [{ json: { ...prevData, risk_summary } }];

// Approval Email placeholder - logs instead of sending
// In production, this will be a Gmail/SMTP node
const data = $input.first().json;
console.log('[WARDEN] Would send approval email to:', $env.WARDEN_ADMIN_EMAIL);
console.log('[WARDEN] Subject: [WARDEN] Action Required:', data.target_service, '—', data.requesting_agent);
return [{ json: data }];

